// Photos — everything the apex knows about it: origin, gateway allowlist, route, Apps-section
// entry (web-app-suite.md F4). Generated by scripts/new-web-app.sh; adding this file IS the
// registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, V1_INSTALL_AT_MS, type HostedApp } from '../types'

declare global {
  interface ImportMetaEnv {
    /** The Photos app's origin (see `apps/registry/apps/photos.ts`). */
    readonly VITE_PHOTOS_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/photos` calls: its `ProxyMethod` table in
// `web/photos/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way).
// ⚠ Exact names, not `photo.*`: `photo.get` exists and Photos never calls it, and a prefix would
// also grant every `photo.*` handler added later.
// ⚠⚠ Five of Drive's `fs.*` methods, each by name and never `fs.*`: the bytes are Drive's surface
// (photos-app.md §43). `fs.getPreview` (tiles), `fs.getLargePreview` (the viewer's rung) and the
// three streaming ops (video playback through the Service Worker, and "Download original"). No
// listing, no `fs.getData`, no write — Photos cannot rename, move, delete or upload a file.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  'sync.health.observe',
  'photo.feedPage',
  'photo.captureTimes',
  'photo.details',
  'photo.motionClip',
  'photo.albums',
  'photo.albums.observe',
  'photo.albumPhotos',
  'photo.albumsFor',
  'photo.createAlbum',
  'photo.renameAlbum',
  'photo.deleteAlbum',
  'photo.addToAlbum',
  'photo.removeFromAlbum',
  'photo.favourites',
  'photo.favourites.observe',
  'photo.isFavourite',
  'photo.setFavourite',
  'photo.trashed',
  'photo.trash.observe',
  'photo.trash',
  'photo.restore',
  'photo.deleteForever',
  'fs.getPreview',
  'fs.getLargePreview',
  'fs.openContentStream',
  'fs.readContentRange',
  'fs.closeContentStream',
]

const PROD_ORIGIN = 'https://photos.tenshu.app'

export const photos: HostedApp = {
  id: 'photos',
  order: 30,
  title: 'Photos',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_PHOTOS_ORIGIN',
  devPort: 5178,
  origin: () => appOrigin(import.meta.env.VITE_PHOTOS_ORIGIN, PROD_ORIGIN, 5178),
  methods: METHODS,
  routePath: 'photos/*',
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'photos',
    label: 'Photos',
    description: 'Your photos and videos, end-to-end encrypted.',
    version: '0.1.0',
    installedAtMs: V1_INSTALL_AT_MS,
    launchPath: '/photos',
    // ⚠ DISPLAY data, like Drive's and Contacts' — what the app can call is `methods` above (F5).
    permissions: [
      {
        id: 'photos.read',
        label: 'See your photos',
        description: 'Browse your photos and videos, their albums, favourites and trash, and play your videos.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'photos.write',
        label: 'Organise your photos',
        description: 'Make albums, mark favourites, and move photos to the trash, restore or delete them.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'photo',
        label: 'PhotoService',
        reason: 'Keeps your albums, favourites and trash, encrypted client-side.',
      },
      {
        id: 'file',
        label: 'FileService',
        reason: 'Holds the photos and videos themselves, and their previews.',
      },
    ],
  },
}

export default photos
